example.code:
text = "Hello World From Python"
vowels = 0
uppers = 0
for ch in text:
    if ch.lower() in "aeiou":
        vowels += 1
    if ch.isupper():
        uppers += 1
print(f"Vowels: {vowels}")
print(f"Uppercase: {uppers}")
for i, ch in enumerate(text):
    if ch.isupper():
        print(f"{ch} at {i}")

practice.solution:
text = "Room 101 is on floor 3"
digits = 0
spaces = 0
for ch in text:
    if ch.isdigit():
        digits += 1
    if ch == " ":
        spaces += 1
print(f"Digits: {digits}")
print(f"Spaces: {spaces}")
for i, ch in enumerate(text):
    if ch.isdigit():
        print(f"{ch} at {i}")
